#!/usr/bin/env node
import esbuild from 'esbuild';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const rootDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const githubRoot = path.resolve(rootDir, '../github');
const srcDir = path.join(rootDir, 'src');
const distDir = path.join(rootDir, 'dist');
const outFile = path.join(distDir, 'dcpGhRunner.js');
const stagedFile = path.join(rootDir, 'dcpGhRunner.js');

const banner = '/* Generated by xframe/dcp-gh-runner/scripts/build-dcp-bundle.js — do not edit. */';

const result = await esbuild.build({
  entryPoints: [path.join(srcDir, 'index.js')],
  write: false,
  bundle: true,
  platform: 'browser',
  format: 'iife',
  globalName: '__dcpGhRunnerBundle',
  target: ['es2020'],
  minify: true,
  legalComments: 'none',
  inject: [path.join(srcDir, 'shims/inject-globals.js')],
  plugins: [{
    name: 'github-browser-shims',
    setup(build) {
      build.onResolve({ filter: /\/github\/src\/http\.js$/ }, () => ({
        path: path.join(srcDir, 'browser/http.js'),
      }));
      build.onResolve({ filter: /\/github\/src\/constants\.js$/ }, () => ({
        path: path.join(srcDir, 'constants.js'),
      }));
      build.onResolve({ filter: /^\.\/executor\.js$/ }, (args) => {
        const importer = args.importer.replace(/\\/g, '/');
        if (importer.includes('/github/src/github/')) {
          return { path: path.join(srcDir, 'browser/log-format.js') };
        }
      });
      build.onResolve({ filter: /\/github\/src\/github\/crypto\.js$/ }, () => ({
        path: path.join(srcDir, 'browser/crypto.js'),
      }));
      build.onResolve({ filter: /\/github\/src\/github\/jit-config\.js$/ }, () => ({
        path: path.join(srcDir, 'browser/jit-config.js'),
      }));
      build.onResolve({ filter: /\/github\/src\/github\/auth\.js$/ }, () => ({
        path: path.join(srcDir, 'browser/auth.js'),
      }));
      build.onResolve({ filter: /\/github\/src\/github\/broker\.js$/ }, () => ({
        path: path.join(srcDir, 'browser/broker.js'),
      }));
      build.onResolve({ filter: /\/github\/src\/github\/registration\.js$/ }, () => ({
        path: path.join(srcDir, 'browser/registration.js'),
      }));
    },
  }],
});

const bundled = result.outputFiles[0].text;
const wrapped = `${banner}
module.declare([], function (require, exports, module) {
${bundled}
  exports.runPipeline = __dcpGhRunnerBundle.runPipeline;
  exports.transcodeVideoFromUrl = __dcpGhRunnerBundle.transcodeVideoFromUrl;
  exports.publishDirectToLinkedIn = __dcpGhRunnerBundle.publishDirectToLinkedIn;
  exports.publishViaGithubCommit = __dcpGhRunnerBundle.publishViaGithubCommit;
  exports.runOneShotListener = __dcpGhRunnerBundle.runOneShotListener;
});
`;

fs.mkdirSync(distDir, { recursive: true });
fs.writeFileSync(outFile, wrapped);
fs.writeFileSync(stagedFile, wrapped);
console.log(`Wrote ${path.relative(rootDir, outFile)} (${(wrapped.length / 1024).toFixed(1)} KB)`);
